B.vV=new A.aQ(B.ci,["Count cartoons","Shows how many cartoons are left","Just the minutes, no cartoon count","Not in the cartoon voice yet: {n}. Try another word, or the phone voice will say it.","It's your turn to pick tonight!","Siblings mode","ON","OFF","Children","The voice calls everyone ticked","Who\u2019s watching tonight","Add a child","Remove","Child {n}","Not used in Siblings mode","Who picks tonight","One child chooses all night, taking turns","Tick at least one child","Who picks tonight?","It\u2019s {n}\u2019s pick!","{n} chooses the cartoons tonight","{n}, tomorrow is your turn","{n} picks tonight!"],t.l)
B.NB=new A.aQ(B.ci,["Conta i cartoni","Mostra quanti cartoni mancano","Solo i minuti, senza contare i cartoni","Non ancora nella voce del cartone: {n}. Prova un\u2019altra parola, altrimenti la legger\xe0 la voce del telefono.","Stasera scegli tu!","Modalit\xe0 fratelli","S\xcc","NO","Bambini","La voce chiama tutti quelli spuntati","Chi guarda stasera","Aggiungi un bambino","Rimuovi","Bambino {n}","Non usato in modalit\xe0 fratelli","Chi sceglie stasera","Un bambino sceglie per tutta la sera, a turno","Spunta almeno un bambino","Chi sceglie stasera?","Stasera sceglie {n}!","{n} sceglie i cartoni stasera","{n}, domani tocca a te","Stasera sceglie {n}!"],t.l)
B.NJ=new A.aQ(B.ci,["Contar dibujos","Muestra cu\xe1ntos dibujos quedan","Solo los minutos, sin contar dibujos","A\xfan no est\xe1 en la voz del dibujo: {n}. Prueba otra palabra o la leer\xe1 la voz del tel\xe9fono.","\xa1Esta noche eliges t\xfa!","Modo hermanos","S\xcd","NO","Ni\xf1os","La voz llama a todos los marcados","Qui\xe9n ve esta noche","A\xf1adir un ni\xf1o","Quitar","Ni\xf1o {n}","No se usa en modo hermanos","Qui\xe9n elige esta noche","Un ni\xf1o elige toda la noche, por turnos","Marca al menos un ni\xf1o","\xbfQui\xe9n elige hoy?","\xa1Hoy elige {n}!","{n} elige los dibujos esta noche","{n}, ma\xf1ana te toca a ti","\xa1Esta noche elige {n}!"],t.l)
B.NC=new A.aQ(B.ci,["Compter les dessins anim\xe9s","Affiche combien de dessins anim\xe9s il reste","Juste les minutes, sans compter les dessins anim\xe9s","Pas encore dans la voix du dessin anim\xe9 : {n}. Essaie un autre mot, sinon la voix du t\xe9l\xe9phone le lira.","Ce soir, c'est toi qui choisis !","Mode fratrie","OUI","NON","Enfants","La voix appelle tous ceux coch\xe9s","Qui regarde ce soir","Ajouter un enfant","Retirer","Enfant {n}","Pas utilis\xe9 en mode fratrie","Qui choisit ce soir","Un enfant choisit toute la soir\xe9e, chacun son tour","Coche au moins un enfant","Qui choisit ce soir ?","C\u2019est {n} qui choisit !","{n} choisit les dessins anim\xe9s ce soir","{n}, demain c\u2019est ton tour","Ce soir, c\u2019est {n} qui choisit !"],t.l)
